class Solution {
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        int id1 = 0;
        int id2 = 0;
        int idx = 0;
        int[] r = new int[m+n];
        while(id1<m && id2<n){
            if(nums1[id1] < nums2[id2]){
                r[idx++] = nums1[id1++];
            } else {
                r[idx++] = nums2[id2++];
            }
        }
        while(id1 < m) r[idx++] = nums1[id1++];
        while(id2 < n) r[idx++] = nums2[id2++];
        for(int i=0;i<m+n;i++) nums1[i] = r[i];
        return;
    }
}
